from math import inf

def bottom_up_cut_rod(p, n):
    r = [0] * (n + 1)      # r[j] = max revenue for a rod of length j
    s = [0] * (n + 1)      # s[j] = length of the first piece in an optimal cut
    for j in range(1, n + 1):
        best = -inf
        for i in range(1, j + 1):
            if p[i] + r[j - i] > best:
                best = p[i] + r[j - i]
                s[j] = i
        r[j] = best
    return r, s

def cut_rod_solution(p, n):
    r, s = bottom_up_cut_rod(p, n)
    pieces = []
    remaining = n
    while remaining > 0:
        pieces.append(s[remaining])
        remaining -= s[remaining]
    return r[n], pieces

if __name__ == "__main__":
    p = {1: 1, 2: 5, 3: 8, 4: 9, 5: 10,
         6: 17, 7: 17, 8: 20, 9: 24, 10: 30}
    for n in (4, 5, 10):
        value, pieces = cut_rod_solution(p, n)
        print(n, value, pieces)
